-- ============================================
-- LUMA — Thème 3 : LONG 3/3 x4 — Un entretien qui se termine par une contre-offre
-- ============================================


update scenarios set content = '{"characters": {"recruiter": "le recruteur", "manager": "le manager actuel"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "Congratulations, we''d love to offer you the position! Can you start in three weeks?", "text_fr": "Félicitations, on aimerait vous offrir le poste ! Vous pouvez commencer dans trois semaines ?", "choices": [{"text": "That''s wonderful news, yes, three weeks works for me.", "text_fr": "C''est une excellente nouvelle, oui, trois semaines me conviennent.", "next": "n2"}, {"text": "Thank you so much! I just need to formally resign first, but that should work.", "text_fr": "Merci beaucoup ! Je dois juste démissionner formellement d''abord, mais ça devrait marcher.", "next": "n2"}]}, "n2": {"speaker": "recruiter", "text": "Perfect, I''ll send over the official offer letter today.", "text_fr": "Parfait, je vous envoie la lettre d''offre officielle aujourd''hui.", "choices": [{"text": "Thank you, I''m really excited to join the team.", "text_fr": "Merci, je suis vraiment ravi de rejoindre l''équipe.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(That evening, you tell your current manager you''re resigning.)", "text_fr": "(Ce soir-là, vous annoncez à votre manager actuel que vous démissionnez.)", "choices": [{"text": "(Prepare to hand in your resignation professionally.)", "text_fr": "(Prépare-toi à remettre ta démission professionnellement.)", "next": "n4"}]}, "n4": {"speaker": "manager", "text": "Wait, you''re leaving? I had no idea you were unhappy here.", "text_fr": "Attendez, vous partez ? Je n''avais aucune idée que vous étiez malheureux ici.", "choices": [{"text": "It''s not about being unhappy, just a great new opportunity.", "text_fr": "Ce n''est pas une question d''être malheureux, juste une belle opportunité.", "next": "n5"}, {"text": "Honestly, I''ve felt a bit stagnant here for a while.", "text_fr": "Honnêtement, je me sens un peu stagnant ici depuis un moment.", "next": "n5b"}]}, "n5": {"speaker": "manager", "text": "I understand. Before you decide anything final — can we talk about what it would take to keep you?", "text_fr": "Je comprends. Avant de décider quoi que ce soit de final — on peut discuter de ce qu''il faudrait pour vous garder ?", "choices": [{"text": "Sure, I''m open to hearing what you have in mind.", "text_fr": "Bien sûr, je suis ouvert à entendre ce que vous avez en tête.", "next": "n6"}, {"text": "I appreciate that, but I''m fairly set on this new opportunity.", "text_fr": "J''apprécie, mais je suis assez fixé sur cette nouvelle opportunité.", "next": "n6b"}]}, "n5b": {"speaker": "manager", "text": "That''s fair feedback. Let''s talk about what could change that, before you make a final decision.", "text_fr": "C''est un retour honnête. Parlons de ce qui pourrait changer ça, avant que vous preniez une décision finale.", "choices": [{"text": "Okay, I''m willing to hear you out.", "text_fr": "D''accord, je suis prêt à vous écouter.", "next": "n6"}]}, "n6": {"speaker": "manager", "text": "We could offer a promotion and a 15% raise if you stay. What do you think?", "text_fr": "On pourrait offrir une promotion et une augmentation de 15% si vous restez. Qu''en pensez-vous ?", "choices": [{"text": "That''s a generous offer — I''ll need some time to think this through.", "text_fr": "C''est une offre généreuse — j''ai besoin de temps pour bien y réfléchir.", "next": "n7"}, {"text": "I appreciate that a lot, but the new role offers growth I can''t get here.", "text_fr": "J''apprécie beaucoup, mais le nouveau poste offre une croissance que je ne peux pas avoir ici.", "next": "n7b"}]}, "n6b": {"speaker": "manager", "text": "I understand, but I''d still like you to consider it — this matters to the team.", "text_fr": "Je comprends, mais j''aimerais quand même que vous y réfléchissiez — ça compte pour l''équipe.", "choices": [{"text": "Alright, I''ll think about it seriously, I promise.", "text_fr": "D''accord, j''y réfléchirai sérieusement, promis.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(That night, you weigh both offers carefully — growth vs. loyalty and comfort.)", "text_fr": "(Ce soir-là, vous pesez les deux offres soigneusement — croissance contre loyauté et confort.)", "choices": [{"text": "(Decide the new opportunity''s growth potential wins out.)", "text_fr": "(Décide que le potentiel de croissance de la nouvelle opportunité l''emporte.)", "next": "n8"}, {"text": "(Decide the counter-offer and familiar team actually feels right.)", "text_fr": "(Décide que la contre-offre et l''équipe familière semblent en fait justes.)", "next": "n8b"}]}, "n7b": {"speaker": "manager", "text": "I respect that. Just know the door''s always open if things change.", "text_fr": "Je respecte ça. Sachez juste que la porte est toujours ouverte si les choses changent.", "choices": [{"text": "Thank you, that really means a lot to me.", "text_fr": "Merci, ça compte vraiment beaucoup pour moi.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(You call the recruiter back to confirm your decision.)", "text_fr": "(Vous rappelez le recruteur pour confirmer votre décision.)", "choices": [{"text": "(Confirm you''re accepting the new position.)", "text_fr": "(Confirme que tu acceptes le nouveau poste.)", "next": "n9"}]}, "n8b": {"speaker": "you_thought", "text": "(You call the recruiter to explain you''ll be staying at your current job.)", "text_fr": "(Vous appelez le recruteur pour expliquer que vous allez rester à votre poste actuel.)", "choices": [{"text": "(Explain politely that you''ve decided to stay with your current employer.)", "text_fr": "(Explique poliment que tu as décidé de rester chez ton employeur actuel.)", "next": "n9b"}]}, "n9": {"speaker": "recruiter", "text": "That''s fantastic news! We''re thrilled to have you joining us.", "text_fr": "C''est une nouvelle fantastique ! On est ravis de vous accueillir.", "choices": [{"text": "Thank you, I''m looking forward to starting this new chapter.", "text_fr": "Merci, j''ai hâte de commencer ce nouveau chapitre.", "next": "end_new_job"}]}, "n9b": {"speaker": "recruiter", "text": "I completely understand, thank you for letting us know so promptly.", "text_fr": "Je comprends totalement, merci de nous l''avoir fait savoir si rapidement.", "choices": [{"text": "Thank you for understanding, and for the wonderful opportunity.", "text_fr": "Merci de votre compréhension, et pour cette merveilleuse opportunité.", "next": "end_stayed"}]}, "end_new_job": {"speaker": "recruiter", "text": "Welcome aboard! We can''t wait to see what you''ll bring to the team.", "text_fr": "Bienvenue à bord ! On a hâte de voir ce que vous apporterez à l''équipe.", "end": true, "ending_label": "Nouvelle opportunité choisie avec assurance 🚀"}, "end_stayed": {"speaker": "manager", "text": "We''re so glad you''re staying. Let''s make that promotion official right away.", "text_fr": "On est tellement content que vous restiez. Rendons cette promotion officielle tout de suite.", "end": true, "ending_label": "Contre-offre acceptée, fidélité récompensée 🏢💼"}}}'::jsonb, is_playable = true
where title = 'Un entretien qui se termine par une contre-offre'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
